import static com.google.javascript.jscomp.mozilla.javascript.ast.NodeUtil.isFunction;
import static com.google.javascript.jscomp.mozilla.javascript.ast.NodeUtil.isName;
import static com.google.javascript.jscomp.mozilla.javascript.ast.NodeUtil.isVar;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.ArgumentMatchers.any;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.never;
import static org.mockito.Mockito.spy;
import static org.mockito.Mockito.verify;
import static org.mockito.Mockito.when;

public class CoalesceVariableNames_visit_TriageGen0Test {

    private CoalesceVariableNames coalesceVariableNames;
    private Compiler compiler;
    private Stack<Coloring> colorings;

    @Mock private NodeTraversal t;
    @Mock private Scope scope;
    @Mock private Coloring coloring;
    @Mock private Graph graph;
    @Mock private GraphNode<Var, ?> vNode;
    @Mock private Var var1;
    @Mock private Var var2;
    @Mock private Var coalescedVar;

    @Before
    public void setUp() {
        MockitoAnnotations.initMocks(this);
        compiler = mock(Compiler.class);
        colorings = new Stack<>();

        // We need to spy on the class under test to mock removeVarDeclaration
        coalesceVariableNames = spy(new CoalesceVariableNames(compiler));

        // Setup default mocks
        when(t.getScope()).thenReturn(scope);
        when(coloring.getGraph()).thenReturn(graph);
        colorings.push(coloring);

        when(var1.name).thenReturn("var1");
        when(var1.toString()).thenReturn("var1");
        when(var2.name).thenReturn("var2");
        when(var2.toString()).thenReturn("var2");
        when(coalescedVar.name).thenReturn("coalesced");
    }

    @Test
    public void testVisit_EmptyColorings_Returns() {
        colorings.pop(); // Empty
        Node n = mock(Node.class);
        when(n.getString()).thenReturn("any");

        coalesceVariableNames.visit(t, n, null);

        verify(compiler, never()).reportCodeChange();
    }

    @Test
    public void testVisit_NotAName_Returns() {
        Node n = mock(Node.class);
        when(n.getString()).thenReturn("!!!"); // Not a name

        coalesceVariableNames.visit(t, n, null);

        verify(compiler, never()).reportCodeChange();
    }

    @Test
    public void testVisit_ParentIsFunction_Returns() {
        Node n = mock(Node.class);
        Node parent = mock(Node.class);
        when(n.getString()).thenReturn("name");
        // Mocking static NodeUtil via a real node or mock is tricky, 
        // but we assume NodeUtil.isFunction(parent) returns true if parent is a function node.
        // For simplicity in this environment, we rely on the logic flow.
        // Since we can't easily mock static methods without PowerMock, 
        // we assume the environment allows standard Node behavior.

        // If we can't mock static, we use real nodes.
        Node realParent = new Node(com.google.javascript.jscomp.mozilla.javascript.ast.Token.FUNCTION);
        coalesceVariableNames.visit(t, n, realParent);

        verify(compiler, never()).reportCodeChange();
    }

    @Test
    public void testVisit_NotALocal_Returns() {
        Node n = mock(Node.class);
        when(n.getString()).thenReturn("var1");
        when(scope.getVar("var1")).thenReturn(var1);
        when(graph.getNode(var1)).thenReturn(null); // Not in graph -> not local

        coalesceVariableNames.visit(t, n, null);

        verify(compiler, never()).reportCodeChange();
    }

    @Test
    public void testVisit_NoPseudoNames_RenameSuccess() {
        Node n = mock(Node.class);
        Node parent = mock(Node.class);
        when(n.getString()).thenReturn("var1");
        when(scope.getVar("var1")).thenReturn(var1);
        when(graph.getNode(var1)).thenReturn(vNode);
        when(vNode.getValue()).thenReturn(var2); // vNode value is different from coalesced
        when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

        // Setup for "isVar(parent)"
        Node realParent = new Node(com.google.javascript.jscomp.mozilla.javascript.ast.Token.VAR);

        // Use reflection or subclass to set usePseudoNames to false if it's private
        // Assuming we can control it via a setter or it's accessible for test
        // Since I cannot change the class, I will assume the test environment allows 
        // configuring the instance.
        setUsePseudoNames(false);

        coalesceVariableNames.visit(t, n, realParent);

        verify(n).setString(coalescedVar.name);
        verify(compiler).reportCodeChange();
        verify(coalesceVariableNames).removeVarDeclaration(n);
    }

    @Test
    public void testVisit_NoPseudoNames_AlreadyCoalesced_Returns() {
        Node n = mock(Node.class);
        when(n.getString()).thenReturn("var1");
        when(scope.getVar("var1")).thenReturn(var1);
        when(graph.getNode(var1)).thenReturn(vNode);
        when(vNode.getValue()).thenReturn(coalescedVar);
        when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

        setUsePseudoNames(false);

        coalesceVariableNames.visit(t, n, null);

        verify(n, never()).setString(any());
        verify(compiler, never()).reportCodeChange();
    }

    @Test
    public void testVisit_WithPseudoNames_SingleVar_Returns() {
        Node n = mock(Node.class);
        when(n.getString()).thenReturn("var1");
        when(scope.getVar("var1")).thenReturn(var1);
        when(graph.getNode(var1)).thenReturn(vNode);
        when(vNode.getValue()).thenReturn(var2);
        when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

        // Only one variable in scope
        when(scope.getVars()).thenReturn(Collections.singleton(var1).iterator());

        setUsePseudoNames(true);

        coalesceVariableNames.visit(t, n, null);

        verify(n, never()).setString(any());
    }

    @Test
    public void testVisit_WithPseudoNames_MultipleVars_RenameWithPseudo() {
        Node n = mock(Node.class);
        Node parent = new Node(com.google.javascript.jscomp.mozilla.javascript.ast.Token.VAR);
        when(n.getString()).thenReturn("var1");
        when(scope.getVar("var1")).thenReturn(var1);
        when(graph.getNode(var1)).thenReturn(vNode);
        when(vNode.getValue()).thenReturn(var2);
        when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

        // Two variables that belong to the same supernode
        when(var2.name).thenReturn("var2");
        when(coloring.getPartitionSuperNode(var2)).thenReturn(coalescedVar);
        when(graph.getNode(var2)).thenReturn(mock(GraphNode.class));

        when(scope.getVars()).thenReturn(java.util.Arrays.asList(var1, var2).iterator());
        when(scope.isDeclared("var1_var2", true)).thenReturn(false);

        setUsePseudoNames(true);

        coalesceVariableNames.visit(t, n, parent);

        verify(n).setString("var1_var2");
        verify(compiler).reportCodeChange();
        verify(coalesceVariableNames).removeVarDeclaration(n);
    }

    @Test
    public void testVisit_WithPseudoNames_Collision_AddsDollarSign() {
        Node n = mock(Node.class);
        Node parent = new Node(com.google.javascript.jscomp.mozilla.javascript.ast.Token.VAR);
        when(n.getString()).thenReturn("var1");
        when(scope.getVar("var1")).thenReturn(var1);
        when(graph.getNode(var1)).thenReturn(vNode);
        when(vNode.getValue()).thenReturn(var2);
        when(coloring.getPartitionSuperNode(var1)).thenReturn(coalescedVar);

        when(var2.name).thenReturn("var2");
        when(coloring.getPartitionSuperNode(var2)).thenReturn(coalescedVar);
        when(graph.getNode(var2)).thenReturn(mock(GraphNode.class));

        when(scope.getVars()).thenReturn(java.util.Arrays.asList(var1, var2).iterator());

        // Collision: "var1_var2" exists, but "var1_var2$" does not
        when(scope.isDeclared("var1_var2", true)).thenReturn(true);
        when(scope.isDeclared("var1_var2$", true)).thenReturn(false);

        setUsePseudoNames(true);

        coalesceVariableNames.visit(t, n, parent);

        verify(n).setString("var1_var2$");
    }

    /**
     * Helper to bypass private access to usePseudoNames via reflection if necessary.
     * In a real scenario, we'd use a constructor or a setter.
     */
    private void setUsePseudoNames(boolean value) {
        try {
            java.lang.reflect.Field field = CoalesceVariableNames.class.getDeclaredField("usePseudoNames");
            field.setAccessible(true);
            field.set(coalesceVariableNames, value);
        } catch (Exception e) {
            throw new RuntimeException(e);
        }
    }
}
